S={'batting':'TAIYEBI XI','bowling':'OPPONENT XI','runs':0,'wickets':0,'balls':0,'overs_limit':0,'striker':'BATTER 1','striker_runs':0,'striker_balls':0,'non_striker':'BATTER 2','non_runs':0,'non_balls':0,'bowler':'BOWLER 1','bowler_runs':0,'bowler_wickets':0,'bowler_balls':0,'recent':[],'target':0,'innings':1,'innings_done':False,'match_finished':False,'winner':'','innings1_score':0,'bowler_number':1}
LOGO='data:image/png;base64,'  # Embedded school logo; no external image file needed

def snap(): return json.loads(json.dumps(S))
def rec(v): S['recent']=(S['recent']+[v])[-6:]
def swap():
    for a,b in [('striker','non_striker'),('striker_runs','non_runs'),('striker_balls','non_balls')]: S[a],S[b]=S[b],S[a]
def over_limit_reached(): return S['overs_limit']>0 and S['balls']>=S['overs_limit']*6
def legal_delivery(wicket=False,faced=True):
    S['balls']+=1; S['bowler_balls']+=1
    if faced:S['striker_balls']+=1
    if wicket:S['wickets']=min(10,S['wickets']+1);S['bowler_wickets']+=1
    return S['balls']%6==0
def finish_innings():
    if S['innings_done'] or S['match_finished']:return
    S['innings_done']=True
    if S['innings']==1:
        S['innings1_score']=S['runs'];S['target']=S['runs']+1
        S['batting'],S['bowling']=S['bowling'],S['batting'];S['innings']=2
        S['runs']=S['wickets']=S['balls']=0;S['striker_runs']=S['striker_balls']=S['non_runs']=S['non_balls']=0
        S['bowler_runs']=S['bowler_wickets']=S['bowler_balls']=0;S['recent']=[]
        S['striker']='BATTER 1';S['non_striker']='BATTER 2';S['bowler_number']=1;S['bowler']='BOWLER 1';S['innings_done']=False
    else:
        S['match_finished']=True
        S['winner']=S['batting'] if S['runs']>=S['target'] else ('TIE' if S['runs']==S['innings1_score'] else S['bowling'])
def check_end():
    if S['innings']==2 and S['runs']>=S['target']:finish_innings();return
    if S['wickets']>=10 or over_limit_reached():finish_innings()
def apply(d):
    a=d.get('action')
    if S['match_finished']:return snap()
    if S['innings_done'] and a not in ('reset','setup','undo'):return snap()
    if a=='score':
        n=max(0,min(6,int(d.get('runs',0))));HIST.append(snap());S['runs']+=n;S['striker_runs']+=n;S['bowler_runs']+=n;rec(str(n) if n else '•')
        oe=legal_delivery();
        if n%2:swap()
        if oe:swap();S['bowler_number']+=1;S['bowler']='BOWLER '+str(S['bowler_number'])
        check_end()
    elif a in ('wide','noball','bye','legbye'):
        HIST.append(snap());n=max(0,int(d.get('runs',0)))
        if a=='wide':S['runs']+=1+n;S['bowler_runs']+=1+n;rec('Wd')
        elif a=='noball':S['runs']+=1+n;S['bowler_runs']+=1+n;S['striker_balls']+=1;rec('Nb')
        else:
            S['runs']+=n;rec('B' if a=='bye' else 'Lb');oe=legal_delivery(faced=False)
            if n%2:swap()
            if oe:swap();S['bowler_number']+=1;S['bowler']='BOWLER '+str(S['bowler_number'])
        check_end()
    elif a=='wicket':
        HIST.append(snap());rec('W');oe=legal_delivery(True);S['striker']='BATTER '+str(S['wickets']+2);S['striker_runs']=S['striker_balls']=0
        if oe:swap();S['bowler_number']+=1;S['bowler']='BOWLER '+str(S['bowler_number'])
        check_end()
    elif a=='undo' and HIST:S.clear();S.update(HIST.pop())
    elif a=='reset':
        HIST.append(snap());
        for k in ('runs','wickets','balls','striker_runs','striker_balls','non_runs','non_balls','bowler_runs','bowler_wickets','bowler_balls','target','innings1_score'):S[k]=0
        S.update(recent=[],innings=1,innings_done=False,match_finished=False,winner='',bowler_number=1,bowler='BOWLER 1')
    elif a=='setup':
        HIST.append(snap())
        # SET MATCH starts a fresh match and clears any previous winner state.
        for k in ('batting','bowling','striker','non_striker','bowler'):
            if d.get(k):S[k]=str(d[k])[:48]
        if d.get('overs_limit') and str(d['overs_limit']).strip():S['overs_limit']=max(1,min(50,int(d['overs_limit'])))
        S.update(runs=0,wickets=0,balls=0,striker_runs=0,striker_balls=0,non_runs=0,non_balls=0,
                 bowler_runs=0,bowler_wickets=0,bowler_balls=0,target=0,innings1_score=0,
                 innings=1,innings_done=False,match_finished=False,winner='',recent=[],bowler_number=1)
        S['bowler']=str(d.get('bowler') or 'BOWLER 1')[:48]
        if d.get('target') and str(d['target']).strip():S['target']=max(0,int(d['target']))
    return snap()

