STRIP=f'''<div class="strip"><div class="seg team"><strong id="batting">TAIYEBI XI</strong><small>(BATTING)</small></div><div class="seg players"><div><span class="name" id="striker">BATTER 1</span><b id="sr">0 0</b></div><div><span class="name" id="non">BATTER 2</span><b id="nr">0 0</b></div></div><div class="seg mid"><strong><span id="runs">0</span>-<span id="wickets">0</span></strong><small><span id="overs">0.0</span>&nbsp; RUN RATE <span id="rr">0.00</span><div id="status" style="margin-top:4px;font-weight:bold"></div></small></div><div class="seg bowling"><div><span class="name" id="bowler">BOWLER 1</span><b id="bf">0-0</b></div><div><span>ECON</span><b id="econ">0.00</b></div><div id="recent">○ ○ ○ ○ ○ ○</div></div><div class="seg team"><strong id="bowling">OPPONENT XI</strong><small>(BOWLING)</small></div></div>'''
JS='''async function refresh(){try{let s=await(await fetch('/data',{cache:'no-store'})).json();for(let k of ['batting','bowling','striker','bowler','runs','wickets'])document.getElementById(k).textContent=s[k];document.getElementById('non').textContent=s.non_striker;document.getElementById('sr').textContent=s.striker_runs+' '+s.striker_balls;document.getElementById('nr').textContent=s.non_runs+' '+s.non_balls;document.getElementById('overs').textContent=Math.floor(s.balls/6)+'.'+s.balls%6;document.getElementById('rr').textContent=s.balls?(s.runs/(s.balls/6)).toFixed(2):'0.00';document.getElementById('bf').textContent=s.bowler_wickets+'-'+s.bowler_runs;document.getElementById('econ').textContent=s.bowler_balls?(s.bowler_runs/(s.bowler_balls/6)).toFixed(2):'0.00';document.getElementById('recent').textContent=(s.recent||[]).join(' ')||'○ ○ ○ ○ ○ ○';let st='OVERS: '+Math.floor(s.balls/6)+'.'+(s.balls%6)+' / '+(Number(s.overs_limit)||'—');if(s.innings===2)st+=' | TARGET '+s.target;if(s.match_finished)st='MATCH COMPLETE';if(s.innings_done)st='INNINGS COMPLETE';document.getElementById('status').textContent=st;showCelebration(s)}catch(e){}}let celebrationShown=false;function showCelebration(s){let box=document.getElementById('winnerbox');if(!box)return;if(s.match_finished){box.style.display='flex';if(!celebrationShown){box.innerHTML='<div class=wininner><div class=trophy>🏆</div><div class=winlabel>'+(s.winner==='TIE'?'MATCH TIED':s.winner+' WINS!')+'</div><div class=winsub>TAIYEBI CRICKET</div><div id=exitWrap style="display:none"><button class=exitBroadcast onclick=exitBroadcast()>EXIT BROADCAST</button></div></div>';celebrationShown=true;confetti();setTimeout(()=>{let w=document.getElementById('exitWrap');if(w)w.style.display='block'},4000)}}else{box.style.display='none';celebrationShown=false}}function exitBroadcast(){let logo=LOGO_DATA;document.body.innerHTML='<main style="min-height:100vh;display:grid;place-items:center;text-align:center;background:radial-gradient(circle,#5b1680,#090516);color:white;font-family:Arial;padding:20px"><section style="padding:30px;border:3px solid #e8c84d;border-radius:24px;background:#27043e;max-width:720px">'+(logo?'<img src="'+logo+'" style="width:min(60vw,220px);border-radius:14px">':'<div style="font-size:80px">🏏</div>')+'<h1 style="color:#e8c84d">THANK YOU FOR WATCHING</h1><p>TAIYEBI CRICKET BROADCAST</p><button onclick="window.close()" style="padding:14px 24px;border-radius:12px;background:#e8c84d;border:0;font-weight:bold">CLOSE THIS TAB</button></section></main>'}function confetti(){let cv=document.getElementById('confetti');if(!cv)return;let x=cv.getContext('2d');cv.width=innerWidth;cv.height=innerHeight;let p=Array.from({length:100},()=>({x:Math.random()*cv.width,y:-Math.random()*cv.height,vy:2+Math.random()*4,vx:-1+Math.random()*2,r:3+Math.random()*4}));let n=0;function frame(){x.clearRect(0,0,cv.width,cv.height);p.forEach(q=>{q.y+=q.vy;q.x+=q.vx;x.fillStyle=['#f4d35e','#e54b7b','#8f44d6','#fff','#41c7a5'][Math.floor(Math.random()*5)];x.fillRect(q.x,q.y,q.r,q.r*1.8);if(q.y>cv.height){q.y=-10;q.x=Math.random()*cv.width}});if(++n<220)requestAnimationFrame(frame);else x.clearRect(0,0,cv.width,cv.height)}frame()}setInterval(refresh,700);refresh();'''.replace('LOGO_DATA','LOGO_DATA')
# Put logo literal into JS safely (base64 data URI, JSON-quoted)
JS=JS.replace('LOGO_DATA',json.dumps(LOGO))
WAITICE='''async function waitIce(pc){if(pc.iceGatheringState==='complete')return;await new Promise(resolve=>{let t=setTimeout(resolve,1000);pc.addEventListener('icegatheringstatechange',()=>{if(pc.iceGatheringState==='complete'){clearTimeout(t);resolve()}},{once:false})})}'''
VIEWERJS='''let viewerRoom=null,viewerConnecting=false,viewerRetryTimer=null,viewerHasVideo=false,viewerStopped=false;function showStandby(msg='CAMERA IS OFFLINE'){const p=document.getElementById('offlinePoster');if(p)p.style.display='flex';const m=document.getElementById('posterMsg');if(m)m.textContent=msg;const v=document.getElementById('cam');if(v&&!viewerHasVideo){try{v.pause();v.srcObject=null}catch(_){}}}function setLive(){viewerHasVideo=true;const p=document.getElementById('offlinePoster');if(p)p.style.display='none';const m=document.getElementById('posterMsg');if(m)m.textContent='LIVE'}function scheduleViewerRetry(){if(viewerStopped||viewerRetryTimer)return;viewerRetryTimer=setTimeout(()=>{viewerRetryTimer=null;if(!viewerRoom&&!viewerConnecting)startViewer()},3000)}async function startViewer(){if(viewerRoom||viewerConnecting||viewerStopped)return;viewerConnecting=true;const v=document.getElementById('cam');try{if(!window.LivekitClient)throw Error('Video library did not load');const r=await fetch('/livekit-token?role=viewer',{cache:'no-store'});if(!r.ok)throw Error(await r.text());const data=await r.json();const room=new LivekitClient.Room({adaptiveStream:false,dynacast:false,autoSubscribe:true});room.on(LivekitClient.RoomEvent.TrackSubscribed,(track,publication,participant)=>{if(track.kind==='video'){try{track.attach(v);v.muted=true;v.autoplay=true;v.playsInline=true;setLive();v.play().catch(()=>{})}catch(e){console.warn('Video attach failed',e)}}else if(track.kind==='audio'){try{const el=track.attach();el.autoplay=true;el.controls=false;el.style.display='none';document.body.appendChild(el);el.play().catch(()=>{document.getElementById('audioHint').textContent='Tap screen to enable audio';document.getElementById('audioHint').style.display='block';document.addEventListener('click',()=>el.play().catch(()=>{}),{once:true})})}catch(_){}}});room.on(LivekitClient.RoomEvent.TrackUnsubscribed,(track)=>{if(track.kind==='video'){try{track.detach(v)}catch(_){};viewerHasVideo=false;showStandby('VIDEO INTERRUPTED — RECONNECTING')}});room.on(LivekitClient.RoomEvent.ParticipantDisconnected,()=>{if(!room.remoteParticipants.size){viewerHasVideo=false;showStandby('HOST OFFLINE — WAITING')}});room.on(LivekitClient.RoomEvent.Disconnected,()=>{if(viewerRoom===room)viewerRoom=null;viewerHasVideo=false;showStandby('CONNECTION LOST — RECONNECTING');scheduleViewerRetry()});await room.connect(data.url,data.token);viewerRoom=room;window.viewerRoom=room;const pubs=[...room.remoteParticipants.values()].flatMap(p=>[...p.trackPublications.values()]).filter(pub=>pub.kind==='video'&&pub.track);if(pubs.length){for(const pub of pubs){try{pub.track.attach(v);v.muted=true;v.autoplay=true;v.playsInline=true;setLive();v.play().catch(()=>{})}catch(e){console.warn(e)}}}else showStandby('WAITING FOR BROADCAST');}catch(e){showStandby('VIDEO CONNECTION FAILED — RETRYING');console.error('Viewer connection error:',e);if(viewerRoom){try{await viewerRoom.disconnect()}catch(_){}viewerRoom=null}scheduleViewerRetry()}finally{viewerConnecting=false}}function closeViewerTab(){viewerStopped=true;if(viewerRetryTimer)clearTimeout(viewerRetryTimer);try{if(viewerRoom)viewerRoom.disconnect()}catch(_){}try{window.close()}catch(_){};setTimeout(()=>{if(!window.closed)location.replace('about:blank')},150)}startViewer();'''

BROADCAST=f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1"><meta http-equiv="Cache-Control" content="no-cache, no-store, must-revalidate"><meta http-equiv="Pragma" content="no-cache"><meta http-equiv="Expires" content="0"><title>Taiyebi Broadcast</title><style>{CSS}</style></head><body><div class="stage"><video id="cam" autoplay playsinline></video><div id="audioHint" style="position:absolute;z-index:9;left:50%;transform:translateX(-50%);bottom:22%;padding:10px 14px;border-radius:12px;background:#180329aa;color:#fff;font-weight:bold;text-align:center;display:none"></div><div class="shade"></div><div class="head"><div class="brand"><div class="crest">{LOGOHTML}</div><div class="brandtxt">TAIYEBI<small>HIGHER SECONDARY SCHOOL</small></div></div><div class="right">TAIYEBI<small>UJJAIN</small></div></div>{STRIP}</div><div id="offlinePoster" class="offlinePoster"><div class="posterCard">{('<img class="posterLogo" src="'+LOGO+'" alt="Taiyebi School logo">') if LOGO else '<div style="font-size:80px">🏏</div>'}<div class="posterTitle">TAIYEBI CRICKET</div><div class="posterSub">BROADCAST</div><div class="posterMsg" id="posterMsg">CAMERA IS OFFLINE</div><button onclick="closeViewerTab()" style="margin-top:18px;padding:12px 20px;border:0;border-radius:10px;background:#e8c84d;color:#210637;font-weight:bold;cursor:pointer">CLOSE THIS TAB</button></div></div><div id="winnerbox" class="winnerbox"></div><canvas id="confetti" class="confetti"></canvas><script src="https://cdn.jsdelivr.net/npm/livekit-client/dist/livekit-client.umd.min.js"></script><script>{JS};{VIEWERJS}</script></body></html>'''
CONTROL=f'''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1,maximum-scale=1"><meta http-equiv="Cache-Control" content="no-cache, no-store, must-revalidate"><meta http-equiv="Pragma" content="no-cache"><meta http-equiv="Expires" content="0"><title>Taiyebi Control</title><style>{CSS}</style></head><body class="controlbody"><div class="stage"><video id="cam" autoplay playsinline muted></video><div class="shade"></div><div class="head"><div class="brand"><div class="crest">{LOGOHTML}</div><div class="brandtxt">TAIYEBI<small>HIGHER SECONDARY SCHOOL</small></div></div><div class="right">MATCH CONTROL<small>UJJAIN</small></div></div>{STRIP}</div><div id="winnerbox" class="winnerbox"></div><canvas id="confetti" class="confetti"></canvas><section class="controls"><h2>TAIYEBI MATCH CONTROL</h2><form id="setup" class="setup"><input name="batting" placeholder="Batting team"><input name="bowling" placeholder="Bowling team"><input name="striker" placeholder="Striker"><input name="non_striker" placeholder="Non-striker"><input name="bowler" placeholder="Bowler"><input name="overs_limit" type="number" min="1" max="50" required placeholder="Enter overs limit"><input name="target" type="number" placeholder="Target"><button>SET MATCH</button></form><div class="btns"><button onclick="send('score',{{runs:0}})">DOT</button><button onclick="send('score',{{runs:1}})">+1</button><button onclick="send('score',{{runs:2}})">+2</button><button onclick="send('score',{{runs:3}})">+3</button><button class="gold" onclick="send('score',{{runs:4}})">FOUR</button><button class="gold" onclick="send('score',{{runs:6}})">SIX</button><button onclick="send('wicket')">WICKET</button><button onclick="send('wide')">WIDE</button><button onclick="send('noball')">NO BALL</button><button onclick="send('bye')">BYE</button><button onclick="send('legbye')">LEG BYE</button><button onclick="send('undo')">UNDO</button><button onclick="send('reset')">RESET</button></div><p><label style="display:inline-block;margin:6px;color:#fff">STREAM QUALITY <select id="quality"><option value="720">720p HD</option><option value="1080">1080p</option><option value="2160">4K (if supported)</option></select></label> <button id="start" class="gold">START CAMERA</button> <button id="switchCam">SWITCH CAMERA</button> <button id="stop">STOP CAMERA</button> <a href="/broadcast" target="_blank">Open broadcast page</a></p><p class="note">Start webcam here; public viewers use the separate broadcast page.</p></section><script src="https://cdn.jsdelivr.net/npm/livekit-client/dist/livekit-client.umd.min.js"></script><script>let stream=null,v=document.getElementById('cam'),hostPeers=[],cameraFacing='environment',hostActive=false,liveRoom=null;function videoConstraints(h){{return {{width:{{ideal:h===2160?3840:h===1080?1920:1280}},height:{{ideal:h===2160?2160:h===1080?1080:720}},frameRate:{{ideal:30,max:30}},facingMode:{{ideal:cameraFacing}}}}}}async function getCamera(h){{try{{return await navigator.mediaDevices.getUserMedia({{video:videoConstraints(h),audio:{{echoCancellation:true,noiseSuppression:true,autoGainControl:true}}}})}}catch(e){{if(h>480)return await navigator.mediaDevices.getUserMedia({{video:{{facingMode:{{ideal:cameraFacing}},width:{{ideal:640}},height:{{ideal:480}}}},audio:true}});throw e}}}}async function startLive(){{let b=document.getElementById('start');if(stream)return;b.disabled=true;b.textContent='STARTING…';try{{if(!navigator.mediaDevices?.getUserMedia)throw Error('Use HTTPS and a supported browser.');stream=await getCamera(parseInt(document.getElementById('quality').value)||720);v.srcObject=stream;v.play().catch(()=>{{}});const r=await fetch('/livekit-token?role=host',{{cache:'no-store'}});if(!r.ok)throw Error(await r.text());const data=await r.json();liveRoom=new LivekitClient.Room({{adaptiveStream:true,dynacast:true}});await liveRoom.connect(data.url,data.token);await liveRoom.localParticipant.publishTrack(stream.getVideoTracks()[0],{{videoEncoding:{{maxBitrate:5000000,maxFramerate:30}},videoCodec:'h264'}});if(stream.getAudioTracks()[0])await liveRoom.localParticipant.publishTrack(stream.getAudioTracks()[0]);hostActive=true;b.textContent='CAMERA ON'}}catch(e){{if(liveRoom){{try{{await liveRoom.disconnect()}}catch(_){{}}}}liveRoom=null;if(stream){{stream.getTracks().forEach(t=>t.stop());stream=null}}v.srcObject=null;alert('Broadcast could not start: '+(e.message||e));b.textContent='START CAMERA'}}finally{{b.disabled=false}}}}document.getElementById('start').onclick=startLive;document.getElementById('switchCam').onclick=async()=>{{if(!stream){{alert('Start the camera first.');return}}cameraFacing=cameraFacing==='environment'?'user':'environment';try{{const ns=await navigator.mediaDevices.getUserMedia({{video:videoConstraints(parseInt(document.getElementById('quality').value)||720),audio:false}});const nt=ns.getVideoTracks()[0],ot=stream.getVideoTracks()[0];const pub=liveRoom.localParticipant.getTrackPublication(LivekitClient.Track.Source.Camera);if(pub?.track){{await pub.track.replaceTrack(nt)}}else await liveRoom.localParticipant.publishTrack(nt);if(ot)ot.stop();stream.removeTrack(ot);stream.addTrack(nt);v.srcObject=stream;await v.play()}}catch(e){{cameraFacing=cameraFacing==='environment'?'user':'environment';alert('Could not switch camera: '+(e.message||e))}}}};document.getElementById('stop').onclick=async()=>{{hostActive=false;if(liveRoom){{try{{await liveRoom.disconnect()}}catch(e){{}}liveRoom=null}}if(stream){{stream.getTracks().forEach(t=>t.stop());stream=null;v.srcObject=null}}document.getElementById('start').textContent='START CAMERA';document.getElementById('start').disabled=false}};async function send(a,x={{}}){{await fetch('/api',{{method:'POST',headers:{{'Content-Type':'application/json'}},body:JSON.stringify({{action:a,...x}})}});refresh()}}document.getElementById('setup').onsubmit=e=>{{e.preventDefault();send('setup',Object.fromEntries(new FormData(e.target).entries()))}};{JS}</script></body></html>'''

class Handler(BaseHTTPRequestHandler):
 def send(self,b,typ='text/html; charset=utf-8',status=200):
  self.send_response(status);self.send_header('Content-Type',typ);self.send_header('Cache-Control','no-store');self.send_header('Content-Length',str(len(b)));self.end_headers();self.wfile.write(b)
 def do_GET(self):
  p=urlparse(self.path).path
  if p=='/':self.send(BROADCAST.encode())
  elif p=='/broadcast':self.send(BROADCAST.encode())
  elif p=='/control':self.send(CONTROL.encode())
  elif p=='/livekit-token':
   role=parse_qs(urlparse(self.path).query).get('role',['viewer'])[0]
   if not (LIVEKIT_URL and LIVEKIT_API_KEY and LIVEKIT_API_SECRET):self.send(json.dumps({'error':'LiveKit credentials not configured'}).encode(),'application/json',503)
   else:
    identity=('host-' if role=='host' else 'viewer-')+str(int(time.time()*1000))
    grants=api.VideoGrants(room_join=True,room=LIVEKIT_ROOM,can_publish=(role=='host'),can_subscribe=True)
    token=api.AccessToken(LIVEKIT_API_KEY,LIVEKIT_API_SECRET).with_identity(identity).with_grants(grants).to_jwt()
    self.send(json.dumps({'url':LIVEKIT_URL,'token':token}).encode(),'application/json')
  elif p=='/data':
   with LOCK:b=json.dumps(snap()).encode()
   self.send(b,'application/json')
  elif p=='/signal/host':
   with SIG_LOCK:offers=[{'id':k,'sdp':v['offer']} for k,v in SIGNALS.items() if v.get('answer') is None and not v.get('sent')];[SIGNALS[k].update(sent=True) for k in SIGNALS if SIGNALS[k].get('answer') is None and not SIGNALS[k].get('sent')]
   self.send(json.dumps({'offers':offers}).encode(),'application/json')
  elif p=='/signal/answer':
   sid=parse_qs(urlparse(self.path).query).get('id',[''])[0]
   with SIG_LOCK:a=SIGNALS.get(sid,{}).get('answer')
   self.send(json.dumps({'sdp':a}).encode(),'application/json')
  else:self.send(b'Not found','text/plain',404)
 def do_POST(self):
  try:
   p=urlparse(self.path).path;length=int(self.headers.get('Content-Length',0));raw=self.rfile.read(length)
   if p=='/api':
    d=json.loads(raw or b'{}')
    with LOCK:r=apply(d)
    self.send(json.dumps(r).encode(),'application/json')
   else:self.send(b'Not found','text/plain',404)
  except Exception as e:self.send(json.dumps({'error':str(e)}).encode(),'application/json',400)
 def log_message(self,*args):pass
if __name__=='__main__':
 print('Public scoreboard: http://127.0.0.1:8080/');print('Controller: http://127.0.0.1:8080/control');print('If logo file is missing, put your logo next to this Python file as taiyebi_logo.png.')
 try:ThreadingHTTPServer((HOST,PORT),Handler).serve_forever()
 except OSError as e:print('Server error:',e)
